from lib import *
S = SS('w22')
steps = [
    step("本机跟 ICMP 有关的内核开关:net.inet.icmp 下有 maskrepl = 0(不回地址掩码请求)、timestamp = 0(不回时间戳请求)、drop_redirect = 1(丢弃收到的重定向)、log_redirect = 0、bmcastecho = 1(会回应发给广播 / 组播的 echo)、suppress_icmp_port_unreach = 0、fraglimit = 16、fragtimeout = 5;net.inet.ip.redirect = 1,net.inet.ip.forwarding = 0(本机不是路由器)。这里没有 icmplim 之类的限速开关:macOS 不像 Linux 那样用 sysctl 设 ICMP 限速,下一节直接测量。netstat -s -p icmp 的 Input histogram 里没有“redirect”一项,Output histogram 里只有 echo reply 和 destination unreachable 两类。", t=tl(S(1)), mark=lidx(S(1), 'net.inet.icmp.maskrepl', 'net.inet.icmp.timestamp', 'net.inet.icmp.drop_redirect', 'icmplim'), done=lidx(S(1), 'net.inet.icmp.bmcastecho', 'net.inet.ip.redirect', 'net.inet.ip.forwarding', 'netstat -s -p icmp'), kv=KV([['maskrepl / timestamp', '都是 0:不回掩码 / 时间戳请求'], ['drop_redirect', '1:丢弃收到的重定向'], ['ip.forwarding', '0:本机不转发,也不发重定向'], ['限速开关', 'net.inet.icmp 下没有']], ['限速开关'])),
    step("ICMP 差错有限速:往 lo0 上没人监听的 UDP 端口以不同间隔持续发包,3 秒内回来的 ICMP 端口不可达个数几乎不变:间隔 0 ms 发了 374,840 个包只回 31 个,间隔 1 ms / 5 ms / 10 ms / 50 ms 时分别发 2,961 / 598 / 300 / 60 个,都只回 30 个——相邻差错的间隔最小 99~100、中位 100 ms,也就是不管发多快最多每 100 ms 回一个(约 10 个/秒)。发得慢于这个速度时每个都回:间隔 200 ms 发 15 个回 15 个(间隔 200 ms),间隔 1000 ms 发 5 个回 5 个(间隔 1000 ms)。netstat 里 icmp_error 的调用次数和“destination unreachable”输出次数也只增加 30 左右——被限掉的包根本没有走到生成 ICMP 这一步。", t=tl(S(2)), mark=lidx(S(2), '间隔      0 ms', '间隔      1 ms', '结论'), done=lidx(S(2), '间隔      5 ms', '间隔     10 ms', '间隔     50 ms', '间隔    200 ms', '间隔   1000 ms'), b=bars([['间隔 0 ms · 发 374,840 → 回', 31, '31'], ['间隔 1 ms · 发 2,961 → 回', 30, '30'], ['间隔 10 ms · 发 300 → 回', 30, '30'], ['间隔 50 ms · 发 60 → 回', 30, '30'], ['间隔 200 ms · 发 15 → 回', 15, '15']], 31, mark=[0, 1, 2, 3], done=[4]), kv=KV([['上限', '约每 100 ms 一个(≈ 10 个/秒)'], ['发得更快', '回的个数不变'], ['发得更慢', '每个都回(200 ms → 15 个/15 个)'], ['netstat 计数', '只增加 30 左右']], ['上限'])),
    step("哪些响应受限:同样往 lo0 猛发,ICMP echo 发出 3000 个请求收到 3000 个应答,没有被限速;TCP 对没人监听的端口连续 connect 1500 次(0.07 秒),抓到 1500 个 SYN,回了 1500 个 RST,也没有被限速;而 UDP 端口不可达在 3 秒内发了 374,840 个只回了 31 个。所以这一限速针对的是 ICMP 差错报文(这里测到的是端口不可达),不是 ICMP 整体,也不是 TCP 的 RST。其它类型的差错(如超时、需要分片)是否同样受限,这里没有测。", t=tl(S(3)), mark=lidx(S(3), 'UDP 端口不可达(ICMP)'), done=lidx(S(3), 'ICMP echo', 'TCP:'), b=bars([['echo 应答 · 发 3000 → 回', 3000, '3000'], ['TCP RST · 发 1500 SYN → 回', 1500, '1500'], ['UDP 端口不可达 · 发 374,840 → 回', 31, '31']], 3000, mark=[2], done=[0, 1]), kv=KV([['echo 应答', '3000 / 3000,没有限速'], ['TCP RST', '1500 / 1500,没有限速'], ['ICMP 差错(端口不可达)', '374,840 个里只回 31 个']], ['ICMP 差错(端口不可达)'])),
    step("路由器也限速:对默认网关的关闭端口发 100 个 UDP 包(间隔 1 ms,共约 103 ms),只收到 4 个端口不可达;把 TTL 设成 1 发 100 个,只收到 3 个超时报文。回应都集中在最初的几毫秒(相邻间隔 0~2 ms),之后就不再回——和本机“每 100 ms 一个”不同,这台网关的行为更像先放行几个再停,具体算法和配置看不到。所以 traceroute 里的星号、只回 1/3 的跳,有一部分可能只是路由器在限速,不一定是路径有问题。", t=tl(S(4)), mark=lidx(S(4), '端口不可达(发到网关', '超时(TTL=1'), done=lidx(S(4), '设备各有各的策略'), b=bars([['发到网关关闭端口 100 个 → 回', 4, '4'], ['TTL=1 发 100 个 → 回', 3, '3']], 100, mark=[0, 1], done=[]), kv=KV([['网关(端口不可达)', '100 个只回 4 个'], ['网关(超时)', '100 个只回 3 个'], ['回应时间', '都在最初几毫秒内'], ['含义', 'traceroute 的星号可能只是限速']], ['含义'])),
    step("ICMP 时间戳和地址掩码请求:macOS 的 net.inet.icmp.timestamp = 0、maskrepl = 0。用非特权 ICMP 套接字向 127.0.0.1 发时间戳请求(类型 13),1 秒内套接字只收到一个类型 13 的包(请求自己的副本),没有收到应答类型 14;地址掩码请求(类型 17)同样只收到类型 17,没有应答类型 18;作为对照,echo 请求(类型 8)收到了应答类型 0。这些请求本机都没有回应,与两个 sysctl 为 0 一致。", t=tl(S(5)), mark=lidx(S(5), '时间戳请求(类型 13)', '地址掩码请求(类型 17)'), done=lidx(S(5), '回显请求(类型 8,对照)'), kv=KV([['时间戳请求(13)', '没有应答 14'], ['地址掩码请求(17)', '没有应答 18'], ['echo 请求(8)', '有应答 0']], ['时间戳请求(13)'])),
]
